    internal sealed record Query(string Name, PhysicsShape Shape, Pose Pose, MapPickRay Ray);

    internal static Query[] Queries()
    {
        var queries = new[] { "crate", "short-post", "hanging-post", "fallen-log", "mesh-ramp", "doorway" }
            .Select(id =>
            {
                var placement = MapPlacementShapes.Resolve(NativeWorldFixtures.Placed(id, yaw: 0.371f).Resolved).Single();
                return new Query(id, placement.Collider!, placement.WorldPose, new(new(0.1f, 0.1f, -4), Vector3.UnitZ, 10));
            }).ToList();
        queries.Add(new("aperture-miss", Aperture(), Pose.Identity, new(Vector3.Zero, Vector3.UnitZ, 10)));
        queries.Add(new("aperture-hit", Aperture(), Pose.Identity, new(new(1.5f, 0, 0), Vector3.UnitZ, 10)));
        queries.Add(new("inside-box", new BoxShape(Vector3.One), Pose.Identity, new(Vector3.Zero, new(1, 2, 3), 10)));
        queries.Add(new("inside-cylinder", new CylinderShape(1, 2), Pose.Identity, new(new(0, 1, 0), Vector3.UnitX, 10)));
        queries.Add(new("inside-hull", new ConvexHullShape(Corners()), Pose.Identity, new(Vector3.Zero, Vector3.UnitZ, 10)));
        queries.Add(new("tilted-cylinder", new CylinderShape(.3f, .4f),
            new(new(2, 3, -1), Quaternion.CreateFromAxisAngle(Vector3.UnitZ, .63f)),
            new(new(2, 3.1f, -4), Vector3.UnitZ, 10)));
        return queries.ToArray();
    }

    static Vector3[] Corners() => Enumerable.Range(0, 8).Select(i =>
        new Vector3((i & 1) == 0 ? -1 : 1, (i & 2) == 0 ? -1 : 1, (i & 4) == 0 ? -1 : 1)).ToArray();

    static TriangleMeshShape Aperture() => new(
        new Vector3[] { new(-2, -2, 2), new(-1, -2, 2), new(-2, 2, 2), new(-1, 2, 2),
            new(1, -2, 2), new(2, -2, 2), new(1, 2, 2), new(2, 2, 2) },
        new[] { 0, 1, 2, 1, 3, 2, 4, 5, 6, 5, 7, 6 });

    internal static string Snapshot(Query query, bool generic = false)
    {
        bool found;
        double distance;
        Vector3 normal;
        PhysicsShape envelopeShape;
        Pose envelopePose;
        float raise;
        (double MinX, double MinY, double MinZ, double MaxX, double MaxY, double MaxZ) bounds;
        if (generic)
        {
            var ray = query.Ray;
            found = ShapeRayQueries.Cast(new(ray.Origin.X, ray.Origin.Y, ray.Origin.Z,
                ray.Direction.X, ray.Direction.Y, ray.Direction.Z, ray.MaxDistance), query.Shape, query.Pose, out var hit);
            distance = hit.Distance;
            normal = hit.Normal;
            (envelopeShape, envelopePose, raise) = PropQueryGeometry.RaiseEnvelope(query.Shape, query.Pose, 1f);
            bounds = PropQueryGeometry.Bounds(query.Shape, query.Pose);
        }
        else
        {
            found = MapShapeQueries.Raycast(query.Ray, query.Shape, query.Pose, out distance, out normal);
            var envelope = MapInteractionEnvelope.Build(query.Name, query.Shape, true, query.Pose);
            envelopeShape = envelope.Shape;
            envelopePose = envelope.WorldPose;
            raise = envelope.RaiseMetres;
            var box = MapShapeBounds.Of(query.Shape, query.Pose);
            bounds = (box.MinX, box.MinY, box.MinZ, box.MaxX, box.MaxY, box.MaxZ);
        }
        return query.Name + "|" + found + "|" + D(distance) + "|" + V(normal) + "|" +
            string.Join(",", new[] { bounds.MinX, bounds.MinY, bounds.MinZ, bounds.MaxX, bounds.MaxY, bounds.MaxZ }.Select(D)) +
            "|" + D(raise) + "|" + V(envelopePose.Position) + "|" + Shape(envelopeShape);
    }

    internal static string Shape(PhysicsShape shape) => shape switch
    {
        BoxShape box => "B(" + V(box.HalfExtents) + ")",
        CylinderShape cylinder => "C(" + D(cylinder.Radius) + "," + D(cylinder.Length) + ")",
        ConvexHullShape hull => "H[" + string.Join("/", hull.Points.Select(V)) + "]",
        TriangleMeshShape mesh => "M[" + string.Join("/", mesh.Vertices.Select(V)) + "][" + string.Join(",", mesh.Indices) + "]",
        CompoundShape compound => "P[" + string.Join("/", compound.Children.Select(c =>
            V(c.Local.Position) + ":" + V(new(c.Local.Orientation.X, c.Local.Orientation.Y, c.Local.Orientation.Z)) +
            "," + D(c.Local.Orientation.W) + ":" + Shape(c.Shape))) + "]",
        _ => throw new NotSupportedException(),
    };

    static string D(double value) => value.ToString("R", CultureInfo.InvariantCulture);
    static string V(Vector3 value) => D(value.X) + "," + D(value.Y) + "," + D(value.Z);
}
